"use client";
import { useEffect, useState } from "react";
type Product={id:string;name:string;category:string|null;sellingPrice:number|string;stockQuantity:number};
export default function ItemsPage(){const [q,setQ]=useState("");const [products,setProducts]=useState<Product[]>([]);const [loading,setLoading]=useState(true);async function load(){setLoading(true);try{const r=await fetch(`/api/products${q?`?search=${encodeURIComponent(q)}`:""}`);const d=await r.json();if(r.ok)setProducts(d.products)}finally{setLoading(false)}}useEffect(()=>{const t=setTimeout(load,250);return()=>clearTimeout(t)},[q]);return <main className="min-h-screen bg-[#0b0b0b] p-5 text-white md:p-8"><div className="mx-auto max-w-6xl"><header className="mb-7"><p className="text-xl font-bold">TX <span className="text-orange-500">RetailOS</span></p><h1 className="mt-5 text-2xl font-semibold">Products</h1></header><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search products by name..." className="field mb-6"/>{loading?<p className="py-12 text-center text-white/40">Loading products...</p>:<div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{products.map(p=><article key={p.id} className="rounded-2xl border border-white/10 bg-[#151515] p-5"><div className="mb-5 h-28 rounded-xl bg-white/5"/><h2 className="font-semibold">{p.name}</h2><p className="mt-1 text-xs text-white/40">{p.category||"Uncategorised"}</p><div className="mt-5 grid grid-cols-2 gap-3"><div><p className="text-xs text-white/40">Price</p><p className="mt-1 font-medium">₦{Number(p.sellingPrice).toLocaleString()}</p></div><div><p className="text-xs text-white/40">Stock</p><p className="mt-1 font-medium">{p.stockQuantity} units</p></div></div></article>)}{!products.length&&<p className="col-span-full py-12 text-center text-white/30">No products found.</p>}</div>}</div></main>}
